"""
    Fixes album/artist name.
    """
def fix_name(name: Any) -> object {
    name = str(name).strip();
    if name.endswith(")") {
        name = name.rsplit("(", 1)[0].rstrip();
    }
    name = name.replace(".", " ");
    return name;
}

"""

    Get the item at the given path of keys by repeated [] lookups in obj.

    Work around https://github.com/BD2KGenomics/toil/issues/2214

    """
def lookup_key_path(job: Any, `obj: Any, path: Any) -> object {
    for key in path {
        `obj = `obj[key];
    }
    return `obj;
}

